import{_ as s,c as t,o as n,j as e,a as r}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"爻象第十二","description":"杭氏易学 - 爻象第十二","frontmatter":{"title":"爻象第十二","description":"杭氏易学 - 爻象第十二"},"headers":[],"relativePath":"zh/classics/hangshi/013.md","filePath":"zh/classics/hangshi/013.md"}'),l={name:"zh/classics/hangshi/013.md"};function i(c,a,o,d,p,h){return n(),t("div",null,[...a[0]||(a[0]=[e("h1",{id:"爻象第十二",tabindex:"-1"},[r("爻象第十二 "),e("a",{class:"header-anchor",href:"#爻象第十二","aria-label":"Permalink to “爻象第十二”"},"​")],-1),e("p",null,"爻分于卦，卦之象即爻之象。卦由爻变，爻之象亦卦之变象也。《说卦》广象，半为卦变言之。名隶于卦，而重实在爻。六十四卦，《彖》、《象》要皆以象之交易变易反易而互变其义，以定其辞。变之所在，即象之所在。所谓“辞也者，各指其所之”是也。变不同，象亦不同。或一爻变，或二爻变，或三爻变。三爻变者，则为对象。以一卦全变，本体之象已不见，所谓伏也。若二爻或一爻变，则变其半而存其半，京氏所以有半象之说也。向来讲《易》者莫明京氏半象之义，往往置之不论。焦理堂氏《易通释》宗虞仲翔氏之说者也，乃驳其半象，不遗余力。谓“坎之半即巽之半，坤之半即艮之半”云云，而不知京说之正谓“坎半即巽半，坤半即艮半”耳。孔子《杂卦》，“震起艮止，巽伏兑见”，即发明离坎变化，乃震艮巽兑起止伏见之作用。《虞注》：“小畜密云不雨，谓坎象半见。”即指巽为坎之半耳。惟半象二字，在可解不可解之间。与其谓之半象，不如名之曰爻象为简当而易晓也。一卦六爻，本有风雷山泽水火之爻位。与八卦之正位，有其位即有其象。故仅知卦象，而不明爻象，仍未能尽象义之蕴也。",-1),e("p",null,"爻象有正变之分，亦与卦同。如本卦不变，而分爻取象者，则以其位之上下而象异。如震为足，正象也，爻分震之初则为趾。乾为首，正象也，爻分乾之上则为颠，为额，或为项。而六子分乾坤之爻者，亦得推此义以取象。如艮为乾之上爻，亦有首之象。离得坤之中爻，亦取腹象。此不变之变，即广象之义也。",-1),e("p",null,"其因本卦已变，而爻即随其变而易其象，则必以其时其位之不同，而各异其义，即各异其象。如离为目，正象也，因变巽而为多白眼。艮为山，正象也，因反为震，而变为陵。巽为鸡，正象也，因反为兑，而称鹤。其余变化，各以类求，未可指数也。",-1),e("p",null,"一卦六爻，初爻为足为趾；二爻为胫，为股；三四为心，为腹；上五为首，为面。比例甚多，更论爻而不论卦，可谓专以爻位取象，为爻象之本义矣。",-1)])])}const f=s(l,[["render",i]]);export{_ as __pageData,f as default};
